(1573980, 210760, 25742, '<td valign="top">very good and very strange. effective and disturbing. I both like it and not.</td>', 'very good and very strange. effective and disturbing. I both like it and not.', '2005-07-30 11:58:31.000000', NULL, 1),
(1573981, 210719, 24454, '<td valign="top">The composition of this with the grain and the tones is a perfect fit for an old bathroom like this.    Has kind of a "mood" to it.   Glad I don''t have to use one like that today :)  10</td>', 'The composition of this with the grain and the tones is a perfect fit for an old bathroom like this.    Has kind of a "mood" to it.   Glad I don''t have to use one like that today :)  10', '2005-07-30 11:58:38.000000', NULL, 1),
