INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1574549, 210783, 554, '<td valign="top">excelent use of lighting.....10</td>', 'excelent use of lighting.....10', '2005-07-30 17:03:10.000000', NULL, 1),
(1574550, 210697, 29404, '<td valign="top">cool tones , nice idea</td>', 'cool tones , nice idea', '2005-07-30 17:04:46.000000', NULL, 1),
(1574551, 210861, 554, '<td valign="top">oh no, I''ve seen that before;;;;;;best wishes....8</td>', 'oh no, I''ve seen that before;;;;;;best wishes....8', '2005-07-30 17:05:56.000000', NULL, 1),
(1574556, 210907, 25464, '<td valign="top">Nice contrast, color, lines.  No real focal point.  It would be stronger with a single point of interest.</td>', 'Nice contrast, color, lines.  No real focal point.  It would be stronger with a single point of interest.', '2005-07-30 17:09:22.000000', NULL, 1),
(1574560, 210753, 25464, '<td valign="top">This is nice and interesting.  I think I would have liked it better if the subject were in the right third of the frame and rotated for more of a profile, but this is nice as is.</td>', 'This is nice and interesting.  I think I would have liked it better if the subject were in the right third of the frame and rotated for more of a profile, but this is nice as is.', '2005-07-30 17:11:27.000000', NULL, 1),
(1574562, 210711, 25464, '<td valign="top">I like the treatment here.  The lighting is interesting.  great texture and detail.  I am not sure about the placement of the subject''s hand.  it looks strained.  A thumb through a belt loop pulling to the side with a more relaxed stance might have appeared more natural.  Good job though.</td>', 'I like the treatment here.  The lighting is interesting.  great texture and detail.  I am not sure about the placement of the subject''s hand.  it looks strained.  A thumb through a belt loop pulling to the side with a more relaxed stance might have appeared more natural.  Good job though.', '2005-07-30 17:13:21.000000', NULL, 1),
(1574564, 210872, 35602, '<td valign="top">Really blurry.  Nice idea though,.</td>', 'Really blurry.  Nice idea though,.', '2005-07-30 17:13:59.000000', NULL, 1),
(1574567, 210832, 25464, '<td valign="top">Interesting.  great color.  Nice comp.  the only thing I dont like is the focal point becomes the bathing suit on the line.  The bathing suit is fine, but It would have been better turned around so that you don''t see the inside since it is where your eye rests.  Sometimes these things are not in our control.  Good job overall.</td>', 'Interesting.  great color.  Nice comp.  the only thing I dont like is the focal point becomes the bathing suit on the line.  The bathing suit is fine, but It would have been better turned around so that you don''t see the inside since it is where your eye rests.  Sometimes these things are not in our control.  Good job overall.', '2005-07-30 17:15:59.000000', NULL, 1),
(1574568, 210917, 554, '<td valign="top">oh well, just another snapshot..................................ya gotta know I''m kidding..10</td>', 'oh well, just another snapshot..................................ya gotta know I''m kidding..10', '2005-07-30 17:16:02.000000', NULL, 1),
(1574571, 210674, 554, '<td valign="top">very cute...10</td>', 'very cute...10', '2005-07-30 17:16:45.000000', NULL, 1),
(1574574, 210788, 35602, '<td valign="top">Hey, is that Stephen King sitting there?  Very close likeness.  Liked the brown tone of the image. Maybe a little sharper.</td>', 'Hey, is that Stephen King sitting there?  Very close likeness.  Liked the brown tone of the image. Maybe a little sharper.', '2005-07-30 17:17:37.000000', NULL, 1),
(1574577, 210652, 35602, '<td valign="top">Nope, no more room, especially if your claustrophopic.</td>', 'Nope, no more room, especially if your claustrophopic.', '2005-07-30 17:18:35.000000', NULL, 1),
(1574578, 210604, 25464, '<td valign="top">The color is very nice.   The angle seems all wrong.  Basically you have two chats going on here and you have split the veiwers interest between the two.  The better photo would have been focused on the left group (since one person is facing the camera.  Another distraction is the cut in half photos on the background wall.    If this couldn''t be avoided, It should be blurred.  I think you have an interesting photojournalistic eye here, but the framing and angle need work.</td>', 'The color is very nice.   The angle seems all wrong.  Basically you have two chats going on here and you have split the veiwers interest between the two.  The better photo would have been focused on the left group (since one person is facing the camera.  Another distraction is the cut in half photos on the background wall.    If this couldn''t be avoided, It should be blurred.  I think you have an interesting photojournalistic eye here, but the framing and angle need work.', '2005-07-30 17:18:51.000000', NULL, 1),
(1574580, 210856, 25464, '<td valign="top">Simple.  Gorgeous.  Maybe a tad more saturation would improve, but I love the play of light and shadow on the ground.</td>', 'Simple.  Gorgeous.  Maybe a tad more saturation would improve, but I love the play of light and shadow on the ground.', '2005-07-30 17:19:49.000000', NULL, 1),
(1574587, 210783, 25464, '<td valign="top">I like this quite a bit, the lighting and idea are great.  I think you should crop this tighter to place the person in the lower left corner of the frame and crop the top down to just above the lamp.  eliminating the edges of the curtain and minimizing the illuminated corner above the lamp or even eliminating the tall lamp all together.  Good detail.</td>', 'I like this quite a bit, the lighting and idea are great.  I think you should crop this tighter to place the person in the lower left corner of the frame and crop the top down to just above the lamp.  eliminating the edges of the curtain and minimizing the illuminated corner above the lamp or even eliminating the tall lamp all together.  Good detail.', '2005-07-30 17:23:03.000000', NULL, 1),
(1574588, 210537, 35602, '<td valign="top">Nice lighting.  Maybe if you did a different angle, rather than straight on, it would have given a great concept of what it might be like to have only one beer left after downing the rest of the pack.</td>', 'Nice lighting.  Maybe if you did a different angle, rather than straight on, it would have given a great concept of what it might be like to have only one beer left after downing the rest of the pack.', '2005-07-30 17:23:19.000000', NULL, 1),
(1574594, 210864, 25464, '<td valign="top">This is a great idea.  I think it could be more dramatic if you actually crop it in tighter to eliminate the edges of the window.  The only thing I don''t like about it past that is the space between the windows, but nothing can be done about that.  The blinds are sufficient to show that you are actually looking out a window, but the subject could place hands up on the glass as well to emphasize.  Good work.</td>', 'This is a great idea.  I think it could be more dramatic if you actually crop it in tighter to eliminate the edges of the window.  The only thing I don''t like about it past that is the space between the windows, but nothing can be done about that.  The blinds are sufficient to show that you are actually looking out a window, but the subject could place hands up on the glass as well to emphasize.  Good work.', '2005-07-30 17:25:52.000000', NULL, 1),
(1574595, 210926, 25464, '<td valign="top">Cute.</td>', 'Cute.', '2005-07-30 17:26:41.000000', NULL, 1),
(1574599, 210884, 25464, '<td valign="top">This is gorgeous.  I am usually one to say crop tighter, but this leaves me wanting to see a bit more.  Beautiful saturation, color, detail. etc.</td>', 'This is gorgeous.  I am usually one to say crop tighter, but this leaves me wanting to see a bit more.  Beautiful saturation, color, detail. etc.', '2005-07-30 17:27:47.000000', NULL, 1),
