(1579014, 210756, 35602, '<td valign="top">Shutter was too slow on this one.  Made it too hazy.</td>', 'Shutter was too slow on this one.  Made it too hazy.', '2005-08-01 19:57:49.000000', NULL, 1),
(1579021, 210674, 13688, '<td valign="top">i think you had an award winning idea.  for me you needed to show a fuller view, bring in a another light (it appears as though you''re just using window light and it wasn''t quite enough), and get a greater depth of field on your focus.  you also needed to get all your horizontal lines, horizontal.  the hardest part is the idea, the other stuff will come much easier with a bit more time.</td>', 'i think you had an award winning idea.  for me you needed to show a fuller view, bring in a another light (it appears as though you''re just using window light and it wasn''t quite enough), and get a greater depth of field on your focus.  you also needed to get all your horizontal lines, horizontal.  the hardest part is the idea, the other stuff will come much easier with a bit more time.', '2005-08-01 20:00:49.000000', NULL, 1),
(1579023, 210609, 35602, '<td valign="top">You must have applied a filter to this one.  It was creative, but I really didn''t like the final result.  Could you have left one item in the image without the affect and still meet the advanced editing guidelines?</td>', 'You must have applied a filter to this one.  It was creative, but I really didn''t like the final result.  Could you have left one item in the image without the affect and still meet the advanced editing guidelines?', '2005-08-01 20:01:56.000000', NULL, 1),
